def preserve_legacy_payments(apps, schema_editor):
    """Represent existing all-or-nothing payments without losing their method or date."""
    Invoice = apps.get_model('playhouse', 'PlayhouseInvoice')
    Payment = apps.get_model('playhouse', 'PlayhousePayment')
    db = schema_editor.connection.alias
    allowed = {'cash', 'pos', 'card_transfer'}
    for invoice in Invoice.objects.using(db).filter(is_paid=True).iterator():
        method = invoice.payment_method or ''
        if method not in allowed:
            # Legacy invoices without a recorded method remain readable via
            # PlayhouseInvoice.paid_amount's compatibility fallback.
            continue
        cafe_total = sum(
            (item.price * item.quantity for item in invoice.items.using(db).all()),
            0,
        )
        total = max(0, invoice.time_amount + cafe_total - invoice.discount_amount)
        stamp = invoice.paid_at or invoice.created_at
        Payment.objects.using(db).create(
            session_id=invoice.session_id,
            invoice_id=invoice.pk,
            created_by_id=invoice.operator_id,
            method=method,
            amount=total,
            tracking_code=invoice.tracking_code or '',
            created_at=stamp,
            updated_at=stamp,
        )


